//	    last_error = EXCLUDED.last_error,
//	    retry_at = now() + interval '15 minutes',
//	    updated_at = now()
func (q *Queries) RecordMLRuntimeFailure(ctx context.Context, arg *RecordMLRuntimeFailureParams) error {
	_, err := q.db.Exec(ctx, recordMLRuntimeFailure, arg.Kind, arg.LastError)
	return err
}

